import type { ComponentProps, ReactElement } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";

import SessionDetailRoute from "@/app/(app)/sessions/[sessionId]/page";
import { ErrorState } from "@/components/shared/error-state";
import type { SessionDetailPage } from "@/features/sessions/session-detail-page";

const dependencies = vi.hoisted(() => ({
  getAdditionalStudyCandidates: vi.fn(),
  getCachedDatabasePermissions: vi.fn(),
  getGradingCommentPhrases: vi.fn(),
  getGradingRankBands: vi.fn(),
  getSessionDetail: vi.fn(),
  getSessionGradingSubmissions: vi.fn(),
  getSessionMessageContact: vi.fn(),
  getSessionTestState: vi.fn(),
  kickGradingWorker: vi.fn(),
  SessionDetailPage: vi.fn(() => null),
}));

vi.mock("@/lib/permissions/database-permissions", () => ({
  getCachedDatabasePermissions: dependencies.getCachedDatabasePermissions,
}));
vi.mock("@/features/sessions/detail-data", () => ({ getSessionDetail: dependencies.getSessionDetail }));
vi.mock("@/features/sessions/attendance-data", () => ({ getAdditionalStudyCandidates: dependencies.getAdditionalStudyCandidates }));
vi.mock("@/features/sessions/session-detail-page", () => ({ SessionDetailPage: dependencies.SessionDetailPage }));
vi.mock("@/features/grading-submissions/data", () => ({ getSessionGradingSubmissions: dependencies.getSessionGradingSubmissions }));
vi.mock("@/features/session-tests/data", () => ({ getSessionTestState: dependencies.getSessionTestState }));
vi.mock("@/features/parent-messages/data", () => ({ getSessionMessageContact: dependencies.getSessionMessageContact }));
vi.mock("@/features/settings/system-settings-data", () => ({ getGradingRankBands: dependencies.getGradingRankBands }));
vi.mock("@/features/ai-grading/phrases-data", () => ({ getGradingCommentPhrases: dependencies.getGradingCommentPhrases }));
vi.mock("@/features/ai-grading/kick", () => ({ kickGradingWorker: dependencies.kickGradingWorker }));

const sessionId = "fa70d806-18e0-4b04-af6e-b045156a13fa";

async function renderRoute(permissions: string[], status = "scheduled") {
  dependencies.getCachedDatabasePermissions.mockResolvedValue({ ok: true, permissions });
  dependencies.getSessionDetail.mockResolvedValue({ detail: { id: sessionId, lockedAt: null, status }, ok: true });
  dependencies.getAdditionalStudyCandidates.mockResolvedValue({ ok: true, students: [] });

  return (await SessionDetailRoute({
    params: Promise.resolve({ sessionId }),
    searchParams: Promise.resolve({}),
  })) as ReactElement<ComponentProps<typeof SessionDetailPage>>;
}

afterEach(() => {
  vi.clearAllMocks();
});

describe("Session detail route lock-panel permission wiring", () => {
  it("maps session_ledger.reverse to canReverseLedger and payroll.view to canViewPayroll", async () => {
    const without = await renderRoute(["sessions.view", "sessions.lock"]);
    expect(without.type).toBe(dependencies.SessionDetailPage);
    expect(without.props.canReverseLedger).toBe(false);
    expect(without.props.canViewPayroll).toBe(false);

    const reverseOnly = await renderRoute(["sessions.view", "sessions.lock", "session_ledger.reverse"]);
    expect(reverseOnly.props.canReverseLedger).toBe(true);
    expect(reverseOnly.props.canViewPayroll).toBe(false);

    const payrollOnly = await renderRoute(["sessions.view", "sessions.lock", "payroll.view"]);
    expect(payrollOnly.props.canReverseLedger).toBe(false);
    expect(payrollOnly.props.canViewPayroll).toBe(true);

    const both = await renderRoute(["sessions.view", "session_ledger.reverse", "payroll.view"]);
    expect(both.props.canReverseLedger).toBe(true);
    expect(both.props.canViewPayroll).toBe(true);
  });
});

// Generated by /ship test audit (Claude) — 2026-10-24
// Value: protects=each panel loader's result reaches its own SessionDetailPage prop, and submissionReview is built from bands + phrases only with ai_grading.review;
// fails_when=the Promise.all results are destructured out of order (panels swap data), bands and phrases swap, or review settings load without ai_grading.review;
// why_new=the panel loads moved into one Promise.all; this file only covered the lock-panel flags; seam=none;
// no_claim=loaders and SessionDetailPage are mocked; does not prove the real queries or that the loads run concurrently
describe("Session detail route panel data wiring", () => {
  const gradingSubmissions = { data: [{ ai: null, id: "submission-1" }], ok: true };
  const answerKey = { questions: [{ answer: "B", number: 1 }] };
  const keyWarnings = [{ question: 1, wrongShare: 0.8 }];
  const sessionTest = { data: { test: { answerKey, answerKeyVersion: 3, extraction: null, keyWarnings, status: "key_confirmed" } }, ok: true };
  const messageContact = { saved: null, suggestion: { gradingContactPhone: "0900000000", supervisorName: "Cô Hà" } };
  const bands = [{ label: "Giỏi", minScore: 8 }];
  const phrases = { y1_correct: ["Con làm bài rất tốt."] };

  function mockPanelLoaders() {
    dependencies.getSessionGradingSubmissions.mockResolvedValueOnce(gradingSubmissions);
    dependencies.getSessionTestState.mockResolvedValueOnce(sessionTest);
    dependencies.getSessionMessageContact.mockResolvedValueOnce(messageContact);
  }

  it("passes grading, test and message-contact data and a review built from rank bands and phrases to a reviewer", async () => {
    mockPanelLoaders();
    dependencies.getGradingRankBands.mockResolvedValueOnce(bands);
    dependencies.getGradingCommentPhrases.mockResolvedValueOnce(phrases);

    const page = await renderRoute(["sessions.view", "attendance.view", "ai_grading.view", "ai_grading.review"], "in_progress");

    expect(page.type).toBe(dependencies.SessionDetailPage);
    expect(page.props.gradingSubmissions).toBe(gradingSubmissions);
    expect(page.props.sessionTest).toBe(sessionTest);
    expect(page.props.messageContact).toBe(messageContact);
    expect(page.props.submissionReview).toEqual({
      bands,
      canReview: true,
      canWriteResults: false,
      editable: true,
      key: answerKey,
      keyVersion: 3,
      keyWarnings,
      phrases,
      sessionId,
    });
    expect(dependencies.getSessionMessageContact).toHaveBeenCalledWith(sessionId);
    expect(dependencies.getSessionGradingSubmissions).toHaveBeenCalledWith(sessionId);
    expect(dependencies.getSessionTestState).toHaveBeenCalledWith({ canConfirm: false, canManage: false, editable: true, sessionId });
  });

  it("gives no review and skips the rank-band and phrase loads without ai_grading.review", async () => {
    mockPanelLoaders();

    const page = await renderRoute(["sessions.view", "attendance.view", "ai_grading.view"], "in_progress");

    expect(page.type).toBe(dependencies.SessionDetailPage);
    expect(page.props.gradingSubmissions).toBe(gradingSubmissions);
    expect(page.props.sessionTest).toBe(sessionTest);
    expect(page.props.messageContact).toBe(messageContact);
    expect(page.props.submissionReview).toBeUndefined();
    expect(dependencies.getGradingRankBands).not.toHaveBeenCalled();
    expect(dependencies.getGradingCommentPhrases).not.toHaveBeenCalled();
  });
});

