describe("Session detail route additional-study candidates", () => {
  it("shows an error state when the candidate list cannot be loaded for a marker who can add additional study", async () => {
    dependencies.getAdditionalStudyCandidates.mockResolvedValueOnce({ error: { message: "Không đọc được danh sách học viên." }, ok: false });

    const page = (await renderRoute(["sessions.view", "attendance.mark", "students.view"], "in_progress")) as unknown as ReactElement<ComponentProps<typeof ErrorState>>;

    expect(dependencies.getAdditionalStudyCandidates).toHaveBeenCalledTimes(1);
    expect(page.type).toBe(ErrorState);
    expect(page.props).toMatchObject({
      description: "Không đọc được danh sách học viên.",
      title: "Không tải được học viên học thêm",
    });
  });
});
